style.css:
@-moz-document domain("roblox.com") {
/* -- Seção 2: Fundo Global e Fonte Principal -- */
    body {
        background-image: url("https://i.imgur.com/vvn4sha.gif") !important; /* Seu GIF */
        background-color: #000000 !important;
        background-repeat: repeat !important;
        background-attachment: fixed !important;
        background-position: center center !important;
        
        /* Fonte principal (estilo máquina de escrever) */
        font-family: 'Special Elite', cursive !important;
        color: #cccccc !important; /* Cinza claro "sujo" */
        overflow-x: hidden !important;
    }

    /* -- Seção 3: Cursores "Creepy" -- */
    /* AVISO: Links de um site terceiro. Podem quebrar um dia. */
    html, body {
        cursor: url("https://cur.cursors-4u.net/others/oth-8/oth709.png"), auto !important; 
    }
    a, button, input[type="submit"], .btn, .clickable,
    .game-card-link, .item-card-link {
        cursor: url("https://cur.cursors-4u.net/others/oth-8/oth712.png"), pointer !important;
    }

    /* -- Seção 4: Títulos e Fontes "Creepster" (Terror) -- */
    h1, h2, h3, h4, h5, h6,
    .game-card-name, .game-name, .title,
    .profile-name, .text-header, .text-title,
    .font-header-1, .font-header-2,
    .section-header .section-title {
        font-family: 'Creepster', cursive !important;
        font-weight: normal !important;
        letter-spacing: 2px !important;
        color: #ff3333 !important; /* Vermelho "sangue" */
        /* Efeito de brilho neon vermelho */
        text-shadow: 0 0 3px #ff0000, 0 0 8px #ff0000, 0 0 12px #b30000, 1px 1px 2px #000000 !important;
    }

    /* -- Seção 5: Tema Dark Total e Transparência -- */
    /* Torna quase todos os painéis semi-transparentes */
    .content, #container-main, .container-main, .rbx-body,
    .home-themes .content, .card-item, .menu-vertical-container,
    .section-content, .forum-table, .forum-header, .forum-cell,
    .profile-card-container, .profile-card-full-screen-container,
    .modal-content, .tooltip-inner, .popover, .dropdown-menu,
    .search-input-group .input-group-field,
    .item-card-container, .game-card-container,
    .rbx-header, .left-col-list, .nav-menu-panel,
    #chat-container .chat-container, .chat-header, .chat-body {
        /* Fundo preto/vermelho muito escuro e transparente */
        background-color: rgba(10, 0, 0, 0.8) !important; 
        background-image: none !important;
        border: 1px solid rgba(255, 0, 0, 0.2) !important; /* Borda vermelha sutil */
        box-shadow: none !important;
    }

    /* -- Seção 6: Textos, Links e Ícones -- */
    p, span, div, li, .text-name, .text-link, .link,
    .nav-menu-item .text-lead, .rbx-text-navbar-right,
    .rbx-header .text-nav, .text-footer, .input-field,
    .form-control, .btn-control-xs, .avatar-card-label,
    .item-card-caption, .text-label, .text-secondary {
        color: #cccccc !important;
        text-shadow: 1px 1px 2px #000000 !important;
    }
    
    a, a:link, .text-link {
        color: #ff6666 !important; /* Vermelho claro para links */
        text-decoration: none !important;
        transition: all 0.2s ease;
    }
    
    a:hover, .text-link:hover {
        color: #ffffff !important;
        text-shadow: 0 0 5px #ff6666, 0 0 10px #ff0000; /* Brilho vermelho no hover */
    }

    /* Ícones (muda para vermelho) */
    .icon-alert, .icon-logo, .icon-search, .icon-nav-menu,
    .icon-messages, .icon-settings, .icon-robux {
        filter: invert(15%) sepia(100%) saturate(6000%) hue-rotate(350deg) brightness(1.2) !important;
    }
    
    /* -- Seção 7: Botões e Inputs -- */
    .btn-primary-md, .btn-secondary-md, .btn-control-md, button {
        background-color: rgba(30, 0, 0, 0.8) !important;
        border: 1px solid #ff0000 !important;
        color: #ff6666 !important;
        font-family: 'Special Elite', cursive !important;
        text-shadow: 1px 1px 2px #000;
        transition: all 0.3s ease;
        box-shadow: 0 0 5px rgba(255, 0, 0, 0.3) inset;
    }
    .btn-primary-md:hover, .btn-secondary-md:hover, .btn-control-md:hover, button:hover {
        background-color: #ff0000 !important;
        color: #000000 !important;
        border-color: #ff6666 !important;
        box-shadow: 0 0 10px #ff0000, 0 0 15px #ff0000 !important;
        text-shadow: none !important;
    }
    
    .input-field, .form-control {
        background-color: rgba(0, 0, 0, 0.8) !important;
        border: 1px solid #800000 !important;
        color: #E0E0E0 !important;
    }
    .input-field:focus, .form-control:focus {
        border-color: #ff0000 !important;
        box-shadow: 0 0 5px rgba(255, 0, 0, 0.7) !important;
    }

    /* -- Seção 8: Animações e Efeitos "Creepy" -- */
    
    /* Efeito de hover com brilho vermelho intenso */
    .card-item:hover, .avatar-card-container:hover,
    .game-card-container:hover, .item-card-container:hover {
        transform: scale(1.02);
        box-shadow: 0 0 15px rgba(255, 0, 0, 0.7), 0 0 5px rgba(255, 0, 0, 1) !important;
        border-color: rgba(255, 0, 0, 0.5) !important;
        transition: all 0.2s ease-in-out;
    }
    
    /* Animação de "flicker" (piscar) para as cartas de jogo */
    .game-card-container {
        animation: flicker 8s infinite alternate;
        transition: all 0.2s ease-in-out;
    }

    @keyframes flicker {
        0%, 18%, 22%, 25%, 53%, 57%, 100% {
            box-shadow: 0 0 3px rgba(255, 0, 0, 0.2), 0 0 1px rgba(255, 0, 0, 0.1) !important;
        }
        20%, 24%, 55% {
            box-shadow: 0 0 10px rgba(255, 0, 0, 0.7), 0 0 15px rgba(255, 0, 0, 0.5) !important;
        }
    }
    
    /* Animação de pulsação para o logo do Roblox */
    .icon-logo, .icon-logo-r {
        animation: pulse-red 2s infinite;
    }
    
    @keyframes pulse-red {
        0% { filter: invert(15%) sepia(100%) saturate(6000%) hue-rotate(350deg) brightness(1.2); }
        50% { filter: invert(20%) sepia(100%) saturate(8000%) hue-rotate(350deg) brightness(1.5); }
        100% { filter: invert(15%) sepia(100%) saturate(6000%) hue-rotate(350deg) brightness(1.2); }
    }
    
    /* -- Seção 9: Barra de Rolagem "Creepy" -- */
    ::-webkit-scrollbar {
        width: 12px;
    }
    ::-webkit-scrollbar-track {
        background: #1a0000; /* Fundo vermelho bem escuro */
        border-left: 1px solid #330000;
    }
    ::-webkit-scrollbar-thumb {
        background: #cc0000; /* Barra vermelha */
        border-radius: 6px;
        border: 2px solid #330000; /* Borda escura para a barra */
    }
    ::-webkit-scrollbar-thumb:hover {
        background: #ff3333; /* Vermelho mais claro ao passar o mouse */
    }
}
